import { createServerClient } from '@supabase/ssr'
import { NextResponse, type NextRequest } from 'next/server'

export async function middleware(request: NextRequest) {
  let response = NextResponse.next({
    request: {
      headers: request.headers,
    },
  })

  const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL
  const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY

  // Skip auth check entirely when Supabase is not configured
  if (!supabaseUrl || !supabaseKey) {
    return response
  }

  const supabase = createServerClient(
    supabaseUrl,
    supabaseKey,
    {
      cookies: {
        getAll() {
          return request.cookies.getAll()
        },
        setAll(cookiesToSet) {
          cookiesToSet.forEach(({ name, value, options }) => {
            request.cookies.set(name, value)
          })
          response = NextResponse.next({
            request,
          })
          cookiesToSet.forEach(({ name, value, options }) => {
            response.cookies.set(name, value, options)
          })
        },
      },
    }
  )

  // Check Auth Session
  const { data: { user } } = await supabase.auth.getUser()

  // DEFINITION OF PATHS
  const isAuthPage = request.nextUrl.pathname === '/'; // The Landing Page
  // const isDashboardPage = request.nextUrl.pathname.startsWith('/home');

  // Landing page is publicly accessible for all users (logged in or not)

  // 2. Optional: Protect Dashboard
  /* if (request.nextUrl.pathname.startsWith('/home') && !user) {
    return NextResponse.redirect(new URL('/', request.url))
  } */

  return response
}

export const config = {
matcher: [
    '/((?!_next/static|_next/image|favicon.svg|auth/callback|.*\\.(?:svg|png|jpg|jpeg|gif|webp)$).*)',
  ],
};